/**
 * The festivals' visitors (RFC-020 §2.1, §5.1): the sleigh team and the
 * Sankt Martin lantern walk, flown on a canvas by the scene in
 * components/weather-effects.tsx. No React here.
 *
 * The art is drawn as detailed SVG, part by part (public/festivals/*.svg,
 * generated by docs/rfc/020/art.py), and each part is rasterised once to an
 * ImageBitmap at the screen's pixel ratio, capped at 1.5 as the weather's
 * canvas is. A frame then only moves, rotates and layers those bitmaps: a
 * few dozen drawImage calls whatever the detail. The rig and the gait --
 * where each part sits on its parent, and the gallop and the lantern swing
 * as keyframed curves -- are the groundwork's parts.json (lib/festival-rig.json),
 * read the same way docs/rfc/020/prototype/scene.html reads it.
 *
 * The bitmaps are made in idle time when a festival with a visitor starts
 * and closed when it ends (releaseVisitorSprites), never for a festival that
 * isn't on.
 */

import RIG from "@/lib/festival-rig.json";
import type { VisitorKind } from "@/lib/festival-settings";

type Bitmap = ImageBitmap | HTMLCanvasElement;
type Point = [number, number];

interface PartSpec {
  w: number;
  h: number;
  pivot: number[];
}

const P = RIG.parts as Record<string, PartSpec>;
const G = RIG.rig.gait;
const R = RIG.rig.reindeer;
const SL = RIG.rig.sleigh;
const L = RIG.rig.lantern;
const RAD = Math.PI / 180;

export interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}

/* ---------------------------------------------------------------- sprites */

const PARTS: Record<VisitorKind, string[]> = {
  sleigh: [
    "sleigh",
    "santa-arm",
    "reindeer-body",
    "reindeer-head",
    "reindeer-head-lead",
    "reindeer-tail",
    "reindeer-front-upper",
    "reindeer-front-lower",
    "reindeer-back-upper",
    "reindeer-back-lower",
    "reindeer-front-upper-far",
    "reindeer-front-lower-far",
    "reindeer-back-upper-far",
    "reindeer-back-lower-far",
  ],
  lanterns: ["lantern-sun", "lantern-moon", "lantern-star"],
};

export interface VisitorSprites {
  kind: VisitorKind;
  /** The size the parts were drawn for: parts.json units to CSS pixels. */
  scale: number;
  parts: Record<string, Bitmap>;
  /** Presents (three colours) and a star, for the tap. */
  presents: Bitmap[];
  star: Bitmap;
  /** How long rasterising took, ms: reported by the benchmark (§7.1). */
  ms: number;
}

/** A canvas as a bitmap where the browser can, else the canvas itself. */
async function toBitmap(c: HTMLCanvasElement): Promise<Bitmap> {
  if (typeof createImageBitmap === "function") {
    try {
      const bitmap = await createImageBitmap(c);
      c.width = 0;
      c.height = 0;
      return bitmap;
    } catch {
      // Older WebKit: draw from the canvas.
    }
  }
  return c;
}

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D | null] {
  const c = document.createElement("canvas");
  c.width = Math.max(1, Math.ceil(w));
  c.height = Math.max(1, Math.ceil(h));
  return [c, c.getContext("2d")];
}

/** One part's SVG, drawn at `k` device pixels per parts.json unit. */
async function rasterisePart(name: string, k: number): Promise<Bitmap> {
  const img = new Image();
  img.decoding = "async";
  img.src = `/festivals/${name}.svg`;
  await img.decode();
  const spec = P[name];
  const [c, ctx] = canvas(spec.w * k, spec.h * k);
  ctx?.drawImage(img, 0, 0, c.width, c.height);
  return toBitmap(c);
}

/** A wrapped present, lit from the top left like the rest of the art. */
async function presentSprite(k: number, box: string, ribbon: string): Promise<Bitmap> {
  const s = 34;
  const [c, ctx] = canvas(s * k, s * k);
  if (ctx) {
    ctx.scale(k, k);
    ctx.translate(s / 2, s / 2 + 3);
    const body = ctx.createLinearGradient(-14, -12, 14, 14);
    body.addColorStop(0, box);
    body.addColorStop(1, "rgba(0, 0, 0, 0.25)");
    ctx.fillStyle = box;
    ctx.beginPath();
    ctx.roundRect(-13, -11, 26, 23, 3.5);
    ctx.fill();
    ctx.fillStyle = body;
    ctx.globalAlpha = 0.45;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = ribbon;
    ctx.fillRect(-2.5, -11, 5, 23);
    ctx.fillRect(-13, -2.5, 26, 5);
    // The bow.
    ctx.beginPath();
    ctx.moveTo(0, -11);
    ctx.quadraticCurveTo(-11, -22, -13, -14);
    ctx.quadraticCurveTo(-8, -10, 0, -11);
    ctx.quadraticCurveTo(11, -22, 13, -14);
    ctx.quadraticCurveTo(8, -10, 0, -11);
    ctx.fill();
    ctx.fillStyle = "rgba(255, 255, 255, 0.35)";
    ctx.fillRect(-11, -9, 6, 4);
  }
  return toBitmap(c);
}

/** A four-pointed sparkle with a soft glow, drawn into the sprite (canvas blur is slow on a Pi). */
async function starSprite(k: number): Promise<Bitmap> {
  const s = 30;
  const [c, ctx] = canvas(s * k, s * k);
  if (ctx) {
    ctx.scale(k, k);
    ctx.translate(s / 2, s / 2);
    const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 14);
    glow.addColorStop(0, "rgba(255, 226, 122, 0.85)");
    glow.addColorStop(0.5, "rgba(255, 226, 122, 0.25)");
    glow.addColorStop(1, "rgba(255, 226, 122, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(-15, -15, 30, 30);
    ctx.fillStyle = "#FFE27A";
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4 - Math.PI / 2;
      const r = i % 2 === 0 ? 10 : 3;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(0, 0, 2.2, 0, Math.PI * 2);
    ctx.fill();
  }
  return toBitmap(c);
}

const cache = new Map<string, Promise<VisitorSprites>>();

/** Every bitmap of a visitor, drawn once for this size and pixel ratio; shared by Home and the screensaver. */
export function prepareVisitorSprites(kind: VisitorKind, scale: number, dpr: number): Promise<VisitorSprites> {
  const key = `${kind}|${scale.toFixed(3)}|${dpr}`;
  let ready = cache.get(key);
  if (!ready) {
    ready = (async () => {
      const started = performance.now();
      const k = scale * dpr;
      const names = PARTS[kind];
      const bitmaps = await Promise.all(names.map((n) => rasterisePart(n, k)));
      const presents = await Promise.all([
        presentSprite(k * 1.6, "#E04848", "#FFD24A"),
        presentSprite(k * 1.6, "#4AA8FF", "#FFD24A"),
        presentSprite(k * 1.6, "#3FA877", "#F4EBDD"),
      ]);
      const star = await starSprite(k * 1.6);
      return {
        kind,
        scale,
        parts: Object.fromEntries(names.map((n, i) => [n, bitmaps[i]])),
        presents,
        star,
        ms: performance.now() - started,
      };
    })();
    // A failed load (offline, a missing file) is tried again next time.
    ready.catch(() => cache.delete(key));
    cache.set(key, ready);
  }
  return ready;
}

/** Close the bitmaps (the festival is over, or the screen changed size): a megabyte or two given back. */
export function releaseVisitorSprites(keep?: (kind: VisitorKind, scale: number) => boolean): void {
  for (const [key, ready] of cache) {
    const [kind, scale] = key.split("|");
    if (keep?.(kind as VisitorKind, Number(scale))) continue;
    cache.delete(key);
    void ready
      .then((s) => {
        for (const b of [...Object.values(s.parts), ...s.presents, s.star]) if ("close" in b) b.close();
      })
      .catch(() => undefined);
  }
}

/* ---------------------------------------------------------------- the gait (art.py's curves) */

/** A periodic Catmull-Rom curve through keyframes [phase 0..1, value]. */
function curve(keys: number[][], t: number): number {
  t = ((t % 1) + 1) % 1;
  const n = keys.length;
  for (let i = 0; i < n; i++) {
    const p0 = keys[i][0];
    const p1 = i + 1 < n ? keys[i + 1][0] : keys[0][0] + 1;
    if ((p0 <= t && t < p1) || (i === n - 1 && t >= p0)) {
      const u = (t - p0) / (p1 - p0);
      const v0 = keys[(i - 1 + n) % n][1];
      const v1 = keys[i][1];
      const v2 = keys[(i + 1) % n][1];
      const v3 = keys[(i + 2) % n][1];
      return 0.5 * (2 * v1 + (-v0 + v2) * u + (2 * v0 - 5 * v1 + 4 * v2 - v3) * u * u + (-v0 + 3 * v1 - 3 * v2 + v3) * u * u * u);
    }
  }
  return keys[0][1];
}

const wave = ([a, ph]: number[], t: number, f = 1) => a * Math.sin(2 * Math.PI * (f * t + ph));

type LegKey = keyof typeof G.phase;

interface Pose {
  legs: Record<LegKey, [number, number]>;
  pitch: number;
  bob: number;
  head: number;
  tail: number;
}

function pose(t: number): Pose {
  const legs = {} as Record<LegKey, [number, number]>;
  for (const [leg, ph] of Object.entries(G.phase) as Array<[LegKey, number]>) {
    const kind = leg.split("-")[0] as "front" | "back";
    legs[leg] = [curve(G.legs[kind].upper, t + ph), curve(G.legs[kind].lower, t + ph)];
  }
  const pitch = wave(G.body.pitch, t);
  return {
    legs,
    pitch,
    bob: -G.body.bob[0] * Math.cos(2 * Math.PI * t),
    head: G.head.follow * pitch + wave(G.head.nod, t),
    tail: wave(G.tail.flick, t, G.tail.freq),
  };
}

/* ---------------------------------------------------------------- a pass */

export interface Light {
  /** Fog: the visitor fades in and out of the haze. */
  fog: boolean;
  /** A storm: darker, lit up by the lightning (`flash`, 0..1). */
  storm: boolean;
  flash: number;
}

export interface Pass {
  readonly kind: VisitorKind;
  /** Over: the visitor has left the screen and everything it dropped has landed. */
  readonly done: boolean;
  /** The visitor's own shape, CSS pixels, for the tap target; null once it has gone or been tapped. */
  readonly target: Box | null;
  /** Draw this frame at `ms` since the pass began; returns what it drew over, CSS pixels. */
  draw(ctx: CanvasRenderingContext2D, ms: number, dt: number, wind: number, light: Light): Box | null;
  /** A tap on the visitor: presents and stars come down. Once per pass. */
  tap(): void;
}

/** How long a pass takes, ms: about ten seconds (§2.1). */
export const PASS_MS = 10_000;

interface Drop {
  sprite: Bitmap;
  x: number;
  y: number;
  vx: number;
  vy: number;
  angle: number;
  spin: number;
  age: number;
  life: number;
  star: boolean;
}

const union = (a: Box | null, b: Box | null): Box | null => {
  if (!a) return b;
  if (!b) return a;
  const x = Math.min(a.x, b.x);
  const y = Math.min(a.y, b.y);
  return { x, y, w: Math.max(a.x + a.w, b.x + b.w) - x, h: Math.max(a.y + a.h, b.y + b.h) - y };
};

/** Presents and stars from a tap: they fall with the wind, and the stars fade. */
function dropsAt(sprites: VisitorSprites, x: number, y: number, presents: boolean): Drop[] {
  const rand = (a: number, b: number) => a + Math.random() * (b - a);
  const out: Drop[] = [];
  const n = presents ? 3 : 0;
  for (let i = 0; i < n; i++) {
    out.push({ sprite: sprites.presents[i % 3], x: x + rand(-30, 30), y, vx: rand(-40, 60), vy: rand(-80, 20), angle: rand(-0.4, 0.4), spin: rand(-2, 2), age: 0, life: 6, star: false });
  }
  for (let i = 0; i < 12; i++) {
    out.push({ sprite: sprites.star, x: x + rand(-50, 50), y: y + rand(-30, 30), vx: rand(-120, 120), vy: rand(-160, 40), angle: 0, spin: rand(-3, 3), age: 0, life: rand(1.2, 2.2), star: true });
  }
  return out;
}

function drawDrops(ctx: CanvasRenderingContext2D, drops: Drop[], dt: number, wind: number, sprites: VisitorSprites, height: number): Box | null {
  let box: Box | null = null;
  const k = sprites.scale * 1.6;
  for (let i = drops.length - 1; i >= 0; i--) {
    const d = drops[i];
    d.age += dt;
    d.vy += (d.star ? 260 : 620) * dt;
    d.x += (d.vx + wind * 30) * dt;
    d.y += d.vy * dt;
    d.angle += d.spin * dt;
    const size = (d.star ? 30 : 34) * k;
    if (d.age > d.life || d.y - size > height) {
      drops.splice(i, 1);
      continue;
    }
    ctx.save();
    ctx.globalAlpha = d.star ? Math.max(0, 1 - d.age / d.life) * (0.7 + 0.3 * Math.sin(d.age * 18)) : 1;
    ctx.translate(d.x, d.y);
    ctx.rotate(d.angle);
    ctx.drawImage(d.sprite, -size / 2, -size / 2, size, size);
    ctx.restore();
    box = union(box, { x: d.x - size, y: d.y - size, w: size * 2, h: size * 2 });
  }
  return box;
}

/** Where light falls on the visitor: hazy in fog, dark in a storm until the lightning lights it. */
function applyLight(ctx: CanvasRenderingContext2D, box: Box, ms: number, light: Light) {
  if (!light.storm) return;
  ctx.save();
  ctx.globalCompositeOperation = "source-atop";
  ctx.fillStyle = `rgba(14, 18, 32, ${0.38 * (1 - light.flash)})`;
  ctx.fillRect(box.x, box.y, box.w, box.h);
  if (light.flash > 0) {
    ctx.fillStyle = `rgba(210, 225, 255, ${0.25 * light.flash})`;
    ctx.fillRect(box.x, box.y, box.w, box.h);
  }
  ctx.restore();
  void ms;
}

const fogAlpha = (ms: number, light: Light) => (light.fog ? 0.55 + 0.4 * Math.sin(ms / 1400) : 1);

/** The team's size on this screen: 0.62 of the drawing on a 1080p wall (the prototype's), smaller on a phone. */
export function visitorScale(kind: VisitorKind, width: number, height: number): number {
  if (kind === "sleigh") return Math.min(0.62, Math.max(0.3, width / 3100));
  return Math.min(0.6, Math.max(0.38, height / 1800));
}

/* ---------------------------------------------------------------- the sleigh */

/**
 * The sleigh team: one pass left to right in about ten seconds, on an arc
 * whose height and depth change from pass to pass (never parking over the
 * same card twice running), banking with its path and drifting in the
 * weather's wind.
 */
function sleighPass(sprites: VisitorSprites, width: number, height: number, seed: number): Pass {
  const sc = sprites.scale;
  const parts = sprites.parts;
  // Alternate high and low passes, each a little different.
  const high = seed % 2 === 0;
  const baseY = height * (high ? 0.12 + Math.random() * 0.14 : 0.34 + Math.random() * 0.16);
  const arc = height * (0.04 + Math.random() * 0.07) * (Math.random() < 0.7 ? 1 : -1);
  const teamW = (R.first[0] + R.spacing + 260) * sc;
  let drift = 0;
  let tappedAt = -1;
  let gone = false;
  let target: Box | null = null;
  const drops: Drop[] = [];
  const reins: Array<DOMPoint | null> = [null, null];

  const part = (ctx: CanvasRenderingContext2D, name: string) => {
    const p = P[name];
    ctx.drawImage(parts[name], -p.pivot[0], -p.pivot[1], p.w, p.h);
  };
  const at = (ctx: CanvasRenderingContext2D, x: number, y: number, deg: number, fn: () => void) => {
    ctx.save();
    ctx.translate(x, y);
    if (deg) ctx.rotate(deg * RAD);
    fn();
    ctx.restore();
  };

  const drawDeer = (ctx: CanvasRenderingContext2D, k: number, p: Pose, lead: boolean) => {
    const bp = P["reindeer-body"].pivot;
    const rel = ([x, y]: number[], o: number[] = [0, 0]): Point => [x + o[0] - bp[0], y + o[1] - bp[1]];
    ctx.save();
    ctx.translate(0, p.bob);
    ctx.rotate(p.pitch * RAD);
    const leg = (kind: "front" | "back", far: boolean) => {
      const key = `${kind}${far ? "-far" : ""}` as LegKey;
      const up = `reindeer-${kind}-upper${far ? "-far" : ""}`;
      const lo = `reindeer-${kind}-lower${far ? "-far" : ""}`;
      const [ax, ay] = rel(R.legs[kind], far ? R.far_offset : [0, 0]);
      const j = R.joints[kind];
      const upv = P[up].pivot;
      at(ctx, ax, ay, p.legs[key][0], () => {
        at(ctx, j[0] - upv[0], j[1] - upv[1], p.legs[key][1], () => part(ctx, lo));
        part(ctx, up);
      });
    };
    leg("back", true);
    leg("front", true);
    const [tx, ty] = rel(R.tail);
    at(ctx, tx, ty, p.tail, () => part(ctx, "reindeer-tail"));
    leg("back", false);
    leg("front", false);
    part(ctx, "reindeer-body");
    const [hx, hy] = rel(R.head);
    at(ctx, hx, hy, p.head, () => part(ctx, lead ? "reindeer-head-lead" : "reindeer-head"));
    const [rx, ry] = rel(R.rein_ring);
    reins[k] = ctx.getTransform().transformPoint(new DOMPoint(rx, ry));
    ctx.restore();
  };

  return {
    kind: "sleigh",
    get done() {
      return gone && drops.length === 0;
    },
    get target() {
      return tappedAt >= 0 ? null : target;
    },
    tap() {
      if (tappedAt >= 0 || !target) return;
      tappedAt = performance.now();
      // From under the sleigh, where Santa sits.
      drops.push(...dropsAt(sprites, target.x + 150 * sc, target.y + 150 * sc, true));
    },
    draw(ctx, ms, dt, wind, light) {
      let drawn: Box | null = null;
      const u = ms / PASS_MS;
      if (u <= 1.05) {
        // The weather's gust pushes the team along, and it bobs and banks with it.
        drift += wind * 18 * dt;
        const x = -teamW + u * (width + teamW * 1.15) + drift;
        const y = baseY - Math.sin(Math.min(1, u) * Math.PI) * arc + Math.sin(ms / 1700) * 6 + Math.sin(ms / 800) * 3 * wind;
        const bank = Math.cos(Math.min(1, u) * Math.PI) * -3 * Math.sign(arc) + Math.sin(ms / 900) * 1.5 * wind;
        const t = ms / 1000 / G.period;
        const sp = P.sleigh.pivot;
        const sg = G.sleigh;
        // A tap makes Santa wave, for a second and a half.
        const waving = tappedAt >= 0 && performance.now() - tappedAt < 1500 ? 6 : 1;
        ctx.save();
        ctx.globalAlpha = fogAlpha(ms, light);
        ctx.translate(x, y);
        ctx.rotate(bank * RAD);
        ctx.scale(sc, sc);
        ctx.save();
        ctx.translate(sp[0], sp[1] + wave(sg.bob, t / 2));
        ctx.rotate(wave(sg.sway, t / 2) * RAD);
        part(ctx, "sleigh");
        const arm = SL.arm.at;
        at(ctx, arm[0] - sp[0], arm[1] - sp[1], wave(sg.arm, t * (waving > 1 ? 2.5 : 1)) * waving, () => part(ctx, "santa-arm"));
        const hands = ctx.getTransform().transformPoint(new DOMPoint(SL.reins_from[0] - sp[0], SL.reins_from[1] - sp[1]));
        ctx.restore();
        const bp = P["reindeer-body"].pivot;
        for (let k = 0; k < 2; k++) {
          const p = pose(t + k * G.second_deer_phase);
          ctx.save();
          ctx.translate(R.first[0] + k * R.spacing + bp[0], R.first[1] + bp[1] + Math.sin(ms / 800 + k) * 3 * (0.4 + wind));
          drawDeer(ctx, k, p, k === 1);
          ctx.restore();
        }
        ctx.restore();
        // The reins, under the team, sagging between Santa's hands and the rings.
        const dpr = ctx.getTransform().a || 1;
        ctx.save();
        ctx.globalCompositeOperation = "destination-over";
        ctx.globalAlpha = fogAlpha(ms, light);
        ctx.strokeStyle = "#C9A46E";
        ctx.lineWidth = 2 * dpr * Math.max(0.6, sc / 0.62);
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        for (const r of reins) {
          if (!r) continue;
          ctx.beginPath();
          ctx.moveTo(hands.x, hands.y);
          ctx.quadraticCurveTo((hands.x + r.x) / 2, Math.max(hands.y, r.y) + 26 * sc * dpr, r.x, r.y);
          ctx.stroke();
        }
        ctx.restore();
        // The team's own box: the sleigh and both reindeer, heads and hooves.
        target = { x: x - 10 * sc, y: y - 70 * sc, w: (R.first[0] + R.spacing + 270) * sc, h: 320 * sc };
        drawn = { x: target.x - 24, y: target.y - 24, w: target.w + 48, h: target.h + 48 };
        applyLight(ctx, drawn, ms, light);
        if (x > width + 10) gone = true;
      } else {
        gone = true;
        target = null;
      }
      return union(drawn, drawDrops(ctx, drops, dt, wind, sprites, height));
    },
  };
}

/* ---------------------------------------------------------------- the lantern walk */

/**
 * Sankt Martin's lantern walk (§3.3): children's paper lanterns -- sun, moon,
 * star -- carried on sticks along the bottom of the screen. Each step bobs
 * the stick and the lantern swings behind it like a pendulum, each child a
 * little out of step; the wind swings them further. Alternate passes walk
 * the other way.
 */
function lanternPass(sprites: VisitorSprites, width: number, height: number, seed: number, bottom: number): Pass {
  const sc = sprites.scale;
  const parts = sprites.parts;
  const names = ["lantern-sun", "lantern-moon", "lantern-star", "lantern-sun"];
  const dir = seed % 2 === 0 ? 1 : -1;
  const gap = 170 * sc + Math.random() * 40 * sc;
  const group = gap * (names.length - 1) + 120 * sc;
  // The lanterns' tops ride this high above the bottom edge: clear of the
  // navigation bar, the lantern's own height and a little air, a little
  // higher or lower each pass.
  const lift = bottom + 200 * sc + 10 + Math.random() * 40;
  // The stick, from where the lantern hangs down and back to the child's hand.
  const stick = (dx: number) => [dx * 70 * sc, 190 * sc];
  let tappedAt = -1;
  let gone = false;
  let target: Box | null = null;
  const drops: Drop[] = [];

  return {
    kind: "lanterns",
    get done() {
      return gone && drops.length === 0;
    },
    get target() {
      return tappedAt >= 0 ? null : target;
    },
    tap() {
      if (tappedAt >= 0 || !target) return;
      tappedAt = performance.now();
      drops.push(...dropsAt(sprites, target.x + target.w / 2, target.y + target.h * 0.4, false));
    },
    draw(ctx, ms, dt, wind, light) {
      let drawn: Box | null = null;
      // A walk is slower than a sleigh: the whole width in about twelve seconds.
      const u = ms / (PASS_MS * 1.2);
      if (u <= 1.02) {
        const lead = -group + u * (width + group * 1.05);
        const t = ms / 1000 / L.walk_period;
        const top = height - lift;
        ctx.save();
        ctx.globalAlpha = fogAlpha(ms, light);
        ctx.lineCap = "round";
        for (let i = 0; i < names.length; i++) {
          const lag = i * 0.23;
          const bob = L.bob * Math.abs(Math.sin(Math.PI * (t + lag)));
          const swing = L.swing * Math.sin(2 * Math.PI * (t + lag - L.damping_lag)) * (1 + wind * 0.35) - dir * wind * 4;
          const along = lead + i * gap;
          const x = dir > 0 ? along : width - along;
          const y = top - bob * sc * 2;
          // The stick, from the child's hand below up to where the lantern hangs.
          const [sx, sy] = stick(-dir);
          ctx.strokeStyle = "#8A6236";
          ctx.lineWidth = 4 * sc;
          ctx.beginPath();
          ctx.moveTo(x + sx, y + sy);
          ctx.lineTo(x, y);
          ctx.stroke();
          ctx.save();
          ctx.translate(x, y);
          ctx.rotate(swing * RAD);
          ctx.scale(sc, sc);
          const p = P[names[i]];
          ctx.drawImage(parts[names[i]], -p.pivot[0], -p.pivot[1], p.w, p.h);
          ctx.restore();
        }
        ctx.restore();
        const xs = names.map((_, i) => (dir > 0 ? lead + i * gap : width - lead - i * gap));
        const left = Math.min(...xs) - 90 * sc;
        target = { x: left, y: top - 20 * sc, w: Math.max(...xs) - Math.min(...xs) + 180 * sc, h: 240 * sc };
        drawn = { x: target.x - 40 * sc, y: target.y - 20, w: target.w + 80 * sc, h: lift + 20 };
        applyLight(ctx, drawn, ms, light);
        if (dir > 0 ? left > width : left + target.w < 0) gone = true;
      } else {
        gone = true;
        target = null;
      }
      return union(drawn, drawDrops(ctx, drops, dt, wind, sprites, height));
    },
  };
}

/**
 * One pass of the visitor across a screen of `width` x `height` CSS pixels;
 * `seed` varies the path, `bottom` is what covers the screen's bottom edge
 * (Home's navigation bar), which a walk along the bottom keeps clear of.
 */
export function createPass(sprites: VisitorSprites, width: number, height: number, seed: number, bottom = 0): Pass {
  return sprites.kind === "sleigh" ? sleighPass(sprites, width, height, seed) : lanternPass(sprites, width, height, seed, bottom);
}
